  function duplicateNode(id){
    const n=getNode(id); if(!n) return;
    pushHistory();
    const c=clone(n);
    c.id=uid('node');
    c.label=n.label+' Copy';
    c.stationNumber=nextStationNumber(n.type);
    c.stationTypeCode=stationTypeCode(n.type);
    c.equipmentTag=nextEquipmentTag(n.type,null,c.stationNumber);
    c.x+=35;c.y+=35;
    state.nodes.push(c);renderAll();selectItem('node',c.id);markChanged();
  }

  function deleteNode(id){
    pushHistory();
    // Preserve connectors: endpoints glued to the deleted station become literal floating points.
    state.connectors.forEach(c=>{
      let detached=false;
      if(connectorEndpointIsPort(c.source)&&c.source.station_id===id){
        const p=resolveConnectorEndpoint(c,'source');c.source={type:'point',x:p.x,y:p.y};detached=true;
      }
      if(connectorEndpointIsPort(c.target)&&c.target.station_id===id){
        const p=resolveConnectorEndpoint(c,'target');c.target={type:'point',x:p.x,y:p.y};detached=true;
      }
      if(detached)finalizeConnectorRoleIntent(c,{orphaned:true});
      if(c.linkHalf===true&&c.flowId){
        // The mate half and flow record survive; drop ends at the deleted station.
        const f=getFlow(c.flowId);
        if(f){
          if(f.source?.station_id===id)f.source=null;
          if(f.sink?.station_id===id)f.sink=null;
          f.updatedAt=Date.now();
        }
      }
    });
    state.nodes=state.nodes.filter(n=>n.id!==id);
    selected=null;pendingConnection=null;renderAll();markChanged();
  }

  function resetFlowValues(id){
    // Helpbook Internal Flows Reset: zero a runaway recycle quantity so the
    // loop can be re-solved. Only the quantity resets — P/T state and
    // composition are boundary conditions the next solve needs. Works for
    // ordinary streams and shared link flow records. One undo step.
    const live=getStream(id)||getFlow(id);
    if(!live){toast('Flow not found.');return false;}
    pushHistory();
    live.props=live.props||{};
    live.props.flow='0';
    live.solveStatus='UNSOLVED';
    live.solverMessage='Flow quantity reset to 0 — re-solve to recompute.';
    calculateUniversalStream(live);
    markChanged();
    renderAll();
    toast('Flow quantity reset to 0.');
    return true;
  }

  function deleteStream(id){
    const dead0=state.connectors.find(s=>s.id===id);
    if(dead0?.linkHalf===true&&dead0.flowId){
      // Spec §5.5: deleting one half asks about the pair. OK = delete both
      // halves and the shared flow (one undo step via deleteLinkPair);
      // Cancel = delete only this half, mate stays flagged as unpaired.
      if(findLinkMateAnywhere(dead0)){
        if(confirm('Delete both halves of this link?\n\nOK — delete both halves and the shared flow record.\nCancel — delete only this half; its mate stays flagged as unpaired.')){
          deleteLinkPair(dead0.flowId);
          return;
        }
      }
    }
    pushHistory();
    const dead=state.connectors.find(s=>s.id===id);
    if(dead?.linkHalf===true&&dead.flowId){
      // The shared flow record and the mate half survive; only the deleted
      // half's glued end is cleared (recoverable by re-gluing).
      const f=getFlow(dead.flowId);
      if(f)clearFlowEndForHalf(f,dead);
    }
    state.connectors=state.connectors.filter(s=>s.id!==id);
    selected=null;renderAll();markChanged();
  }

  // Selection-aware delete used by the contextual ribbon commands.
  // deleteNode/deleteStream own pushHistory(), renderAll() and markChanged(),
  // so callers must NOT push a second snapshot for the same gesture.
  function deleteSelected(){
    if(!selected){toast('Nothing is selected.');return false;}
    if(selected.kind==='node'){deleteNode(selected.id);return true;}
    if(selected.kind==='connector'||selected.kind==='stream'){deleteStream(selected.id);return true;}
    selected=null;renderAll();
    return false;
  }

  function showNodeMenu(x,y,id){
    contextMenu.innerHTML=`
      <button data-a="dup">Duplicate station</button>
      <button data-a="rename">Rename</button>
      <button data-a="delete" class="danger">Delete station</button>`;
    contextMenu.style.left=x+'px';contextMenu.style.top=y+'px';contextMenu.style.display='block';
    contextMenu.onclick=e=>{
      const a=e.target.dataset.a;if(!a)return;
      if(a==='dup')duplicateNode(id);
      if(a==='delete')deleteNode(id);
      if(a==='rename'){selectItem('node',id);openStationProperties(id);setTimeout(()=>stationFloatBody.querySelector('#nodeLabel')?.focus(),40);}
      contextMenu.style.display='none';
    };
  }

  function addRoutingDogleg(c,segmentIndex,vertices,point){
    const base=ensureConnectorManualRoute(c,vertices);
    if(segmentIndex<0||segmentIndex>=base.length-1)return;
    const a=base[segmentIndex],b=base[segmentIndex+1];
    const horizontal=Math.abs(a.y-b.y)<1e-7;
    const len=Math.hypot(b.x-a.x,b.y-a.y);
    if(len<24)return;
    const signX=Math.sign(b.x-a.x)||1,signY=Math.sign(b.y-a.y)||1;
    const span=Math.min(40,Math.max(20,len*.25)),off=26;
    let dog=[];
    if(horizontal){
      const lo=Math.min(a.x,b.x)+6,hi=Math.max(a.x,b.x)-6;
      const center=Math.max(lo+span/2,Math.min(hi-span/2,point.x));
      const x1=center-span/2,x2=center+span/2;
      dog=signX>0?[{x:x1,y:a.y},{x:x1,y:a.y+off},{x:x2,y:a.y+off},{x:x2,y:a.y}]
                 :[{x:x2,y:a.y},{x:x2,y:a.y+off},{x:x1,y:a.y+off},{x:x1,y:a.y}];
    }else{
      const lo=Math.min(a.y,b.y)+6,hi=Math.max(a.y,b.y)-6;
      const center=Math.max(lo+span/2,Math.min(hi-span/2,point.y));
      const y1=center-span/2,y2=center+span/2;
      dog=signY>0?[{x:a.x,y:y1},{x:a.x+off,y:y1},{x:a.x+off,y:y2},{x:a.x,y:y2}]
                 :[{x:a.x,y:y2},{x:a.x+off,y:y2},{x:a.x+off,y:y1},{x:a.x,y:y1}];
    }
    setConnectorManualVertices(c,[...base.slice(0,segmentIndex+1),...dog,...base.slice(segmentIndex+1)]);
  }

  function showStreamMenu(x,y,id,segmentIndex=null,vertices=null,worldPoint=null){
    const half=state.connectors.find(c=>c.id===id&&c.linkHalf===true);
    if(half){
      const flow=half.flowId?getFlow(half.flowId):null;
      const mate=flow?findLinkMate(half,state.activePageId):null;
      const complete=flow?flowLinkComplete(flow):false;
      contextMenu.innerHTML=`
      <button data-a="editFlow">Open shared flow properties</button>
        ${mate
          ? '<button data-a="goMate">Go to mate</button>'
          : '<button data-a="makeMate">Create mate at other station</button>'}
        <button data-a="copyHalf">Copy half (Ctrl+C)</button>
        <button data-a="pasteMate">Paste mate (Ctrl+V)</button>
        <button data-a="resetFlow">Reset shared flow values</button>
        <button data-a="delete" class="danger">Delete link half</button>`;
      contextMenu.style.left=x+'px';contextMenu.style.top=y+'px';contextMenu.style.display='block';
      contextMenu.onclick=e=>{
        const a=e.target.dataset.a;if(!a)return;
        if(a==='editFlow')openLinkFlowProperties(half);
        if(a==='makeMate')createLinkMate(id);
        if(a==='goMate')goToLinkMate(id);
        if(a==='copyHalf'){selectItem('connector',id);copySelectedHalf(false);}
        if(a==='pasteMate')pasteClipboardAsMate();
        if(a==='resetFlow')resetFlowValues(half.flowId);
        if(a==='delete')deleteStream(id);
        contextMenu.style.display='none';
      };
      return;
    }
    const s=getStream(id);
    const boundary=s?streamBoundaryType(s):'INTERNAL';
    const legendEligible=s&&boundary!=='UNCONNECTED'&&connectorSolverActive(s);
    contextMenu.innerHTML=`
      <button data-a="edit">Edit stream / connector</button>
      ${Number.isInteger(segmentIndex)?'<button data-a="addDogleg">Add routing dogleg here</button>':''}
      <button data-a="resetRoute">Auto Route / Reset Manual Routing</button>
      ${legendEligible?'<button data-a="addFlowLegend">Add Flow Legend...</button>':''}
      ${legendEligible?`<button data-a="toggleLegend">${flowLegendEligible(s)?'Hide Flow Legend':'Show Flow Legend'}</button>`:''}
      ${boundary==='EXTERNAL_IN'?`<button data-a="toggleR">${s?.quantityMode==='REQUIRED'?'Clear Required Flow':'Mark Required Flow (R)'}</button>
      <button data-a="toggleP">${s?.pressureMode==='FEEDBACK'?'Clear Pressure Feedback':'Mark Pressure Feedback (P)'}</button>`:''}
      <button data-a="resetFlow" title="Helpbook Internal Flows Reset: zero a runaway recycle quantity">Reset flow values</button>
      <button data-a="delete" class="danger">Delete connector</button>`;
    contextMenu.style.left=x+'px';contextMenu.style.top=y+'px';contextMenu.style.display='block';
    contextMenu.onclick=e=>{
      const a=e.target.dataset.a;if(!a)return;
      if(a==='edit'){selectItem('connector',id);if(connectorSolverActive(getStream(id)))openFlowProperties(id);}
      if(a==='addDogleg'){
        const st=getStream(id);if(st&&Number.isInteger(segmentIndex)){pushHistory();addRoutingDogleg(st,segmentIndex,vertices||computedConnectorVertices(st),worldPoint||{x:0,y:0});renderAll();markChanged();}
      }
      if(a==='resetRoute'){
        const st=getStream(id);if(st){pushHistory();resetConnectorAutoRoute(st);renderAll();markChanged();}
      }
      if(a==='toggleLegend'){
        // Legend visibility is a display-layer setting, not an engineering
        // edit — kept out of the undo/redo stack on purpose.
        const st=getStream(id);
        if(st){st.legendHidden=!st.legendHidden;renderWires();}
      }
      if(a==='addFlowLegend'){
        openFlowLegendDialog(id,null);
      }
      if(a==='toggleR'){
        const st=getStream(id);
        if(st){pushHistory();st.quantityMode=st.quantityMode==='REQUIRED'?'KNOWN':'REQUIRED';renderAll();markChanged();}
      }
      if(a==='toggleP'){
        const st=getStream(id);
        if(st){pushHistory();st.pressureMode=st.pressureMode==='FEEDBACK'?'SPECIFIED':'FEEDBACK';renderAll();markChanged();}
      }
      if(a==='resetFlow')resetFlowValues(id);
      if(a==='delete')deleteStream(id);
      contextMenu.style.display='none';
    };
  }

  document.addEventListener('mousedown',e=>{
    if(!contextMenu.contains(e.target)) contextMenu.style.display='none';
  });

  // Robust Drag and Drop + Quick-Placement from Palette to Canvas
  let activeDraggedStencil = null;

  function placeStencilOnCanvas(type, clientX, clientY){
    if(!type) return;
    const rect = world.getBoundingClientRect();
    let x, y;
    if(Number.isFinite(clientX) && Number.isFinite(clientY)){
      x = (clientX - rect.left) / zoom;
      y = (clientY - rect.top) / zoom;
    } else {
      // Place near visible center of viewport
      const vpRect = viewport.getBoundingClientRect();
      const rawX = ((vpRect.width / 2) + viewport.scrollLeft - (rect.left - vpRect.left + viewport.scrollLeft)) / zoom;
      const rawY = ((vpRect.height / 2) + viewport.scrollTop - (rect.top - vpRect.top + viewport.scrollTop)) / zoom;
      const stagger = ((state.nodes.length + 1) % 7) * 26;
      x = (Number.isFinite(rawX) && rawX > 60 && rawX < WORLD_W - 100) ? rawX + stagger : (420 + stagger);
      y = (Number.isFinite(rawY) && rawY > 60 && rawY < WORLD_H - 100) ? rawY + stagger : (260 + stagger);
    }
    if(type === 'universalFlow') createUniversalFlowStencil(x, y);
    else if(type === 'onpageLink') createLinkHalfStencil(x, y, 'onpage');
    else if(type === 'crosspageLink') createLinkHalfStencil(x, y, 'crosspage');
    else createNode(type, x - 95, y - 45);
  }

  document.querySelectorAll('.palette-item').forEach(item=>{
    item.addEventListener('dragstart',e=>{
      activeDraggedStencil = item.dataset.type;
      try {
        e.dataTransfer.setData('application/x-sugar-stencil', item.dataset.type);
        e.dataTransfer.setData('text/plain', item.dataset.type);
        e.dataTransfer.effectAllowed = 'copy';
      } catch(_) {}
    });

    item.addEventListener('dragend', ()=>{
      activeDraggedStencil = null;
    });

    // Double-click to instantly insert at canvas center
    item.addEventListener('dblclick', e=>{
      e.preventDefault();
      placeStencilOnCanvas(item.dataset.type);
    });

    const palName = item.querySelector('.pal-name')?.textContent || 'Station';
    item.title = `Drag to canvas or double-click to add ${palName}`;
  });

  function handleCanvasDrag(e){
    e.preventDefault();
    if(e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
  }

  function handleCanvasDrop(e){
    e.preventDefault();
    e.stopPropagation();
    let type = null;
    try {
      type = e.dataTransfer?.getData('application/x-sugar-stencil') ||
             e.dataTransfer?.getData('text/plain') ||
             e.dataTransfer?.getData('text');
    } catch(_) {}
    if(!type) type = activeDraggedStencil;
    if(!type) return;

    placeStencilOnCanvas(type, e.clientX, e.clientY);
    activeDraggedStencil = null;
  }

  [viewport, worldWrap, world, nodesEl, wireLayer].filter(Boolean).forEach(el=>{
    if(!el) return;
    el.addEventListener('dragenter', handleCanvasDrag);
    el.addEventListener('dragover', handleCanvasDrag);
    el.addEventListener('drop', handleCanvasDrop);
  });

  document.addEventListener('dragover', e=>{
    if(activeDraggedStencil && viewport && viewport.contains(e.target)){
      e.preventDefault();
      if(e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
    }
  });

  document.addEventListener('drop', e=>{
    if(activeDraggedStencil && viewport && viewport.contains(e.target)){
      handleCanvasDrop(e);
    }
  });

  // click blank canvas clears selection/pending
  viewport.addEventListener('mousedown',e=>{
    if(!connectorDrag && (e.target===viewport || e.target===world || e.target===nodesEl || e.target===emptyState)){
      selected=null;pendingConnection=null;renderAll();
    }
  });

  function setZoom(z){
    zoom=Math.max(.45,Math.min(1.55,z));
    world.style.transform=`scale(${zoom})`;
    worldWrap.style.width=(WORLD_W*zoom)+'px';
    worldWrap.style.height=(WORLD_H*zoom)+'px';
    document.getElementById('zoomLabel').textContent=Math.round(zoom*100)+'%';
  }
  document.getElementById('zoomIn').onclick=()=>setZoom(zoom+.1);
  document.getElementById('zoomOut').onclick=()=>setZoom(zoom-.1);
  document.getElementById('zoomReset').onclick=()=>setZoom(1);
  document.getElementById('fitBtn').onclick=()=>{
    if(!state.nodes.length && !state.connectors.length){setZoom(1);viewport.scrollTo(0,0);return;}
    const connectorPts=state.connectors.flatMap(c=>[resolveConnectorEndpoint(c,'source'),resolveConnectorEndpoint(c,'target')]);
    const xs=[...state.nodes.map(n=>n.x),...connectorPts.map(p=>p.x)];
    const ys=[...state.nodes.map(n=>n.y),...connectorPts.map(p=>p.y)];
    const maxXs=[...state.nodes.map(n=>n.x+190),...connectorPts.map(p=>p.x)];
    const maxYs=[...state.nodes.map(n=>n.y+120),...connectorPts.map(p=>p.y)];
    const minX=Math.min(...xs), minY=Math.min(...ys);
    const maxX=Math.max(...maxXs), maxY=Math.max(...maxYs);
    const zx=(viewport.clientWidth-40)/(maxX-minX+40);
    const zy=(viewport.clientHeight-40)/(maxY-minY+40);
    setZoom(Math.min(1.2,zx,zy));
    viewport.scrollTo(Math.max(0,(minX-20)*zoom),Math.max(0,(minY-20)*zoom));
  };

  schemeName.addEventListener('change',()=>{pushHistory();state.name=schemeName.value.trim()||'Untitled Scheme';markChanged();});

  function newScheme(){
    if((state.nodes.length||state.connectors.length) && !confirm('Create a new blank scheme? Unsaved changes will be lost.')) return;
    pushHistory();
    restoreStateObject({
      version: 5,
      name: 'New Massecuite Scheme',
      activePageId: 'page_1',
      pages: [{
        id: 'page_1',
        name: 'Page 1',
        order: 0,
        layout: 'A4',
        orientation: 'landscape',
        zoom: 1,
        nodes: [],
        connectors: []
      }],
      nodes: [],
      connectors: []
    });
    currentProjectFileHandle=null;
  }
  document.getElementById('newBtn').onclick=newScheme;

  function projectFileName(){
    const name=(schemeName.value.trim()||state.name||'Massecuite_Scheme')
      .replace(/[^a-z0-9_-]+/gi,'_')
      .replace(/^_+|_+$/g,'');
    return (name||'Massecuite_Scheme')+'.json';
  }

  function projectJsonText(){
    state.name=schemeName.value.trim()||state.name||'Untitled Scheme';
    return JSON.stringify(canonicalStateObject(state),null,2);
  }

  function saveRecoverySnapshot(jsonText){
    try{
      localStorage.setItem(PROJECT_RECOVERY_KEY,jsonText);
      localStorage.setItem(PROJECT_RECOVERY_KEY+'_meta',JSON.stringify({
        name:state.name||'Untitled Scheme',
        savedAt:new Date().toISOString(),
        version:5
      }));
      return true;
    }catch(err){
      console.warn('Browser recovery snapshot could not be written:',err);
      return false;
    }
  }

  function downloadTextFile(textValue,filename){
    const blob=new Blob([textValue],{type:'application/json;charset=utf-8'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;
    a.download=filename;
    a.style.display='none';
    a.rel='noopener';
    document.body.appendChild(a);
    // Keeping the anchor in the DOM materially improves download reliability
    // in Chromium/WebView/file:// environments.
    a.click();
    setTimeout(()=>{
      try{a.remove();}catch(_){}
      try{URL.revokeObjectURL(url);}catch(_){}
    },5000);
  }

  async function writeProjectHandle(handle,jsonText){
    const writable=await handle.createWritable();
    try{
      await writable.write(jsonText);
      await writable.close();
    }catch(err){
      try{await writable.abort();}catch(_){}
      throw err;
    }
  }

  async function saveProject(){
    let jsonText;
    try{
      jsonText=projectJsonText();
    }catch(err){
      console.error('Project serialization failed:',err);
      alert('Could not save project because the project state could not be serialized:\n\n'+err.message);
      return;
    }

    // Always keep an emergency browser copy first. A blocked browser download
    // must never mean the engineering project is lost.
    const recoverySaved=saveRecoverySnapshot(jsonText);
    const filename=projectFileName();

    // If this page already owns a writable file handle, Save behaves like a
    // desktop application and writes back to the same project file.
    if(currentProjectFileHandle){
      try{
        await writeProjectHandle(currentProjectFileHandle,jsonText);
        toast('Project saved · '+currentProjectFileHandle.name);
        return;
      }catch(err){
        console.warn('Existing project handle write failed; switching to Save As.',err);
        currentProjectFileHandle=null;
      }
    }

    // Preferred Chromium/Edge desktop path: real Save As dialog.
    if(window.isSecureContext && typeof window.showSaveFilePicker==='function'){
      try{
        const handle=await window.showSaveFilePicker({
          suggestedName:filename,
          types:[{
            description:'Massecuite Simulator Project',
            accept:{'application/json':['.json']}
          }]
        });
        await writeProjectHandle(handle,jsonText);
        currentProjectFileHandle=handle;
        toast('Project saved · '+handle.name);
        return;
      }catch(err){
        if(err?.name==='AbortError'){
          toast(recoverySaved?'Save cancelled · recovery copy kept':'Save cancelled');
          return;
        }
        console.warn('Native Save As unavailable; using JSON download fallback.',err);
      }
    }

    // Fallback for file:// previews, embedded browsers and browsers without
    // File System Access API.
    try{
      downloadTextFile(jsonText,filename);
      toast(recoverySaved
        ? 'Project saved in browser + JSON download started'
        : 'JSON download started');
    }catch(err){
      console.error('JSON download fallback failed:',err);
      if(recoverySaved){
        alert('The browser blocked the JSON download, but a recovery copy was saved in this browser.\n\nUse Open Project → Recover Browser Save.');
      }else{
        alert('Could not save the project in this browser.\n\n'+err.message);
      }
    }
  }

  async function loadProjectObject(obj,{fileHandle=null,sourceName='Project'}={}){
    if(!obj || (!Array.isArray(obj.nodes) && !Array.isArray(obj.pages))){
      throw new Error('Invalid Massecuite Simulator project file');
    }
    pushHistory();
    obj.name=obj.name||'Imported Scheme';
    restoreStateObject(obj);
    currentProjectFileHandle=fileHandle;
    toast(sourceName+' opened');
  }

  async function openProjectFromText(textValue,{fileHandle=null,sourceName='Project'}={}){
    let obj;
    try{
      obj=JSON.parse(textValue);
    }catch(err){
      throw new Error('The selected file is not valid JSON: '+err.message);
    }
    await loadProjectObject(obj,{fileHandle,sourceName});
  }

  async function openProject(){
    // Preferred desktop path.
    if(window.isSecureContext && typeof window.showOpenFilePicker==='function'){
      try{
        const [handle]=await window.showOpenFilePicker({
          multiple:false,
          types:[{
            description:'Massecuite Simulator Project',
            accept:{'application/json':['.json']}
          }]
        });
        const file=await handle.getFile();
        await openProjectFromText(await file.text(),{fileHandle:handle,sourceName:file.name});
        return;
      }catch(err){
        if(err?.name==='AbortError')return;
        console.warn('Native Open unavailable; using file-input fallback.',err);
      }
    }

    // Reliable fallback supported by ordinary browsers and embedded previews.
    fileInput.click();
  }

  document.getElementById('saveBtn').onclick=()=>{ void saveProject(); };
  document.getElementById('openBtn').onclick=()=>{ void openProject(); };

  fileInput.addEventListener('change',async e=>{
    const file=e.target.files?.[0];
    if(!file){fileInput.value='';return;}
    try{
      // File-input access does not grant a writable file handle; the next Save
      // will therefore use Save As / download rather than pretending to overwrite.
      await openProjectFromText(await file.text(),{fileHandle:null,sourceName:file.name});
    }catch(err){
      console.error('Project open failed:',err);
      alert('Could not open project:\n\n'+err.message);
    }finally{
      fileInput.value='';
    }
  });

  // Exposed recovery hook for the Scheme Library and emergency recovery.
  function recoverLastBrowserProject(){
    let txt=null;
    try{txt=localStorage.getItem(PROJECT_RECOVERY_KEY);}catch(_){}
    if(!txt){
      alert('No browser recovery project is available.');
      return false;
    }
    try{
      const obj=JSON.parse(txt);
      loadProjectObject(obj,{fileHandle:null,sourceName:'Browser recovery'});
      return true;
    }catch(err){
      alert('The browser recovery project could not be opened:\n\n'+err.message);
      return false;
    }
  }


  document.getElementById('templateBtn').onclick=()=>{
    state.name=schemeName.value.trim()||'Untitled Scheme';
    const key='massecuite_template_'+Date.now();
    localStorage.setItem(key,JSON.stringify(canonicalStateObject(state)));
    const list=JSON.parse(localStorage.getItem('massecuite_template_index')||'[]');
    list.push({key,name:state.name,created:new Date().toISOString()});
    localStorage.setItem('massecuite_template_index',JSON.stringify(list));
    toast('Template saved in this browser');
  };

  document.getElementById('libraryBtn').onclick=()=>{
    let list=[];
    let hasRecovery=false;
    try{
      list=JSON.parse(localStorage.getItem('massecuite_template_index')||'[]');
      hasRecovery=!!localStorage.getItem(PROJECT_RECOVERY_KEY);
    }catch(_){}

    if(!list.length && !hasRecovery){
      alert('No browser recovery project or saved templates are available yet.');
      return;
    }

    const lines=[];
    if(hasRecovery)lines.push('R. Recover last saved project');
    list.forEach((x,i)=>lines.push(`${i+1}. Template · ${x.name}`));

    const ans=prompt('Choose a browser-saved item:\n\n'+lines.join('\n'));
    if(ans===null)return;
    if(hasRecovery && String(ans).trim().toUpperCase()==='R'){
      recoverLastBrowserProject();
      return;
    }

    const idx=parseInt(ans,10)-1;
    if(Number.isNaN(idx)||!list[idx])return;
    const obj=JSON.parse(localStorage.getItem(list[idx].key)||'null');
    if(!obj)return;
    pushHistory();
    restoreStateObject(obj);
    currentProjectFileHandle=null;
    toast('Template loaded');
  };

  document.getElementById('undoBtn').onclick=()=>{
    if(!undoStack.length){toast('Nothing to undo');return;}
    redoStack.push(snapshotStateJSON());
    suppressHistory=true;
    restoreStateObject(JSON.parse(undoStack.pop()));
    suppressHistory=false;
    toast('Undo');
  };
  document.getElementById('redoBtn').onclick=()=>{
    if(!redoStack.length){toast('Nothing to redo');return;}
    undoStack.push(snapshotStateJSON());
    suppressHistory=true;
    restoreStateObject(JSON.parse(redoStack.pop()));
    suppressHistory=false;
    toast('Redo');
  };

  document.getElementById('autoBtn').onclick=()=>{
    if(!state.nodes.length)return;
    pushHistory();
    const indeg={};state.nodes.forEach(n=>indeg[n.id]=0);
    state.streams.filter(s=>streamBoundaryType(s)==='INTERNAL').forEach(s=>{if(indeg[s.toNodeId]!=null) indeg[s.toNodeId]++;});
    const levels={};const queue=state.nodes.filter(n=>indeg[n.id]===0).map(n=>n.id);
    queue.forEach(id=>levels[id]=0);
    const visited=new Set();
    while(queue.length){
      const id=queue.shift();if(visited.has(id))continue;visited.add(id);
      state.streams.filter(s=>streamBoundaryType(s)==='INTERNAL' && s.fromNodeId===id).forEach(s=>{
        levels[s.toNodeId]=Math.max(levels[s.toNodeId]??0,(levels[id]??0)+1);
        indeg[s.toNodeId]--; if(indeg[s.toNodeId]<=0)queue.push(s.toNodeId);
      });
    }
    state.nodes.forEach(n=>{if(levels[n.id]==null)levels[n.id]=0;});
    const buckets={};state.nodes.forEach(n=>(buckets[levels[n.id]]??=[]).push(n));
    Object.entries(buckets).forEach(([lvl,arr])=>{
      arr.forEach((n,i)=>{n.x=80+(+lvl)*280;n.y=80+i*170;});
    });
    renderAll();markChanged();document.getElementById('fitBtn').click();
  };


  function ensurePanDefaults(n){
    if(!n || n.type!=='pan')return;
    const d=nodeDefs.pan.defaults;
    n.params=n.params||{};
    Object.entries(d).forEach(([k,v])=>{if(n.params[k]===undefined)n.params[k]=v;});
    if(!n.params.targetMassecuiteDS && n.params.targetBrix)n.params.targetMassecuiteDS=n.params.targetBrix;
    if(!n.params.massecuiteTemperature && n.params.temperature)n.params.massecuiteTemperature=n.params.temperature;
    if(!n.params.panVapourPressure && n.params.vacuumPressureAbs)n.params.panVapourPressure=n.params.vacuumPressureAbs;
  }


