    const topTan=Math.tan(n('catchallTopConeAngle_deg')*Math.PI/180),vaneCount=360/n('catchallVanePitchAngle_deg'),vapLoad=(liveThermal?panVapourMass*voutV:legacyTotalVap*vinV)/3600,spacing=(PI_SRC*vapDiaMM/vaneCount)-n('catchallVaneThickness_mm'),vaneIn=(vapLoad/(vaneCount*(spacing/1000)*n('catchallInletVelocity_m_s')))*1000,vaneOut=(vapLoad/(n('catchallOutletVelocity_m_s')*(spacing/1000)*vaneCount))*1000,vaneSin=Math.sin(n('catchallVaneAngle_deg')*Math.PI/180);fatal(!(vaneSin>0),'Catchall vane sine must be positive.');const catchOD=vapDiaMM/vaneSin,catchH=.5*(shell/1000-catchOD/1000)*topTan;
