    if(![M,Cry,R,z,pl,pw].every(Number.isFinite))return {ok:false,message:'Centrifugal performance inputs are incomplete for heat-loss calculation.'};
    const mlM=M*(1-Cry), washM=Math.max(0,R*M), mlWater=mlM*(1-Number(ei.DSml)),mlSuc=mlM*Number(ei.DSml)*Number(ei.PUml),mlNs=mlM*Number(ei.DSml)*(1-Number(ei.PUml));
