    sPre.water=mlWater*mlScale+wWater*wScale;sPre.sucrose=mlSuc*mlScale+wSuc*wScale;sPre.ns1=mlNs*mlScale+wNs*wScale;
    const Tg=Number(perf.outputTemperatures?.green),Ts=Number(perf.outputTemperatures?.sugar);const sol=centrifugalSolubilityFromEvaluation(c.evaluation);
