  function centrifugalBalanceClosure(inputMasses, outputStreams){
    const inKeys=CORE_COMPONENT_KEYS;
    const outList=(outputStreams||[]).filter(Boolean);
    const inComp=Object.fromEntries(inKeys.map(k=>[k,p2num(inputMasses?.[k])]));
    const outComp=Object.fromEntries(inKeys.map(k=>[k,0]));
    const outputDetails={};
    outList.forEach(st=>{
      const calc=calculateUniversalStream(st);
      const cm=calc?.componentMassFlows||{};
      outputDetails[st.id]={flowKgH:Number.isFinite(calc?.massKgH)?calc.massKgH:0,status:calc?.status||'UNKNOWN'};
      inKeys.forEach(k=>{outComp[k]+=p2num(cm[k]);});
    });
    const residuals={};
    inKeys.forEach(k=>{residuals[k]=inComp[k]-outComp[k];});
    const inputTotal=inKeys.reduce((a,k)=>a+inComp[k],0);
    const outputTotal=inKeys.reduce((a,k)=>a+outComp[k],0);
    const dryKeys=['sucrose','crystals','invert','ash','ns1','ns2','caco3','cao','fiber'];
    const sucroseKeys=['sucrose','crystals'];
    const nonsugarKeys=['invert','ash','ns1','ns2','caco3','cao','fiber'];
    const waterKeys=['water'];
    const sum=(obj,keys)=>keys.reduce((a,k)=>a+p2num(obj[k]),0);
    residuals.wetMass=inputTotal-outputTotal;
    residuals.componentTotal=inputTotal-outputTotal;
    residuals.drySolids=sum(inComp,dryKeys)-sum(outComp,dryKeys);
    residuals.sucrose=sum(inComp,sucroseKeys)-sum(outComp,sucroseKeys);
    residuals.nonsugar=sum(inComp,nonsugarKeys)-sum(outComp,nonsugarKeys);
    residuals.water=sum(inComp,waterKeys)-sum(outComp,waterKeys);
    const scale=Math.max(1,inputTotal);
    const toleranceKgH=Math.max(1e-3,scale*1e-8);
    const keys=['wetMass','componentTotal','drySolids','sucrose','nonsugar','water',...inKeys];
    const maxResidualKgH=Math.max(...keys.map(k=>Math.abs(p2num(residuals[k]))));
    const ok=maxResidualKgH<=toleranceKgH;
    return {ok,toleranceKgH,maxResidualKgH,inputTotal,outputTotal,inputComponents:inComp,outputComponents:outComp,residuals,outputDetails};
  }

