    openCentrifugalDialog(`${three?'3-Output':'2-Output'} Centrifugal Evaluation`,`#${n.stationNumber} · ${n.label||nodeDefs[n.type].title}`,body,`<span class="cent-footer"><span class="cent-msg" id="cdStatus">Enter actual plant operating data.</span><button class="cent-btn" id="cdCancel">Cancel</button><button class="cent-btn" id="cdPreview">Calculate Performance</button></span>`);
