    if(page==='downtake')return `<div class="pan-design-card"><div class="pan-design-card-head"><span>Downtake & Circulator</span><span>FFE D74:D81</span></div><div class="pan-design-card-body"><div class="pan-design-grid">${pdField('circulationRatio','Circulation Ratio',d.circulationRatio,'tube CSA / downtake CSA')}${pdVal('Total Tube Internal CSA',pdF(r.totalTubeCSA_m2,5),'m²')}${pdVal('Downtake CSA',pdF(r.downtakeCSA_m2,5),'m²')}${pdVal('Downtake Diameter',pdF(r.downtakeDia_mm,2),'mm')}${pdVal('Downtake / Tube Plate',pdF(r.downtakePctTubePlate,3),'%')}${pdVal('Circulator Blade Swing',pdF(r.circulatorBladeSwingDia_mm,2),'mm')}</div></div></div>`;
