  document.getElementById('flowApply').onclick=()=>commitFlowDraft({closeAfterCommit:true});
  document.getElementById('flowApplyKeep').onclick=()=>commitFlowDraft({closeAfterCommit:false});
  document.getElementById('flowDirtyKeep').onclick=()=>document.getElementById('flowDirtyDialog').classList.remove('show');
  document.getElementById('flowDirtyDiscard').onclick=()=>{document.getElementById('flowDirtyDialog').classList.remove('show');closeFlowModalImmediate();};
  document.getElementById('flowDirtyApply').onclick=()=>{if(commitFlowDraft({closeAfterCommit:true}))document.getElementById('flowDirtyDialog').classList.remove('show');};
