  document.getElementById('flowMaximize').onclick=e=>{e.stopPropagation();if(!flowModalWindow.classList.contains('maximized')){const r=flowModalWindow.getBoundingClientRect();flowWindowRestoreGeometry={left:r.left,top:r.top,width:r.width,height:r.height};flowModalWindow.classList.add('maximized');flowModalWindow.classList.remove('minimized');}else{flowModalWindow.classList.remove('maximized');if(flowWindowRestoreGeometry){Object.assign(flowModalWindow.style,{left:flowWindowRestoreGeometry.left+'px',top:flowWindowRestoreGeometry.top+'px',width:flowWindowRestoreGeometry.width+'px',height:flowWindowRestoreGeometry.height+'px'});}}bringFloatingToFront(flowModalWindow);};
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'&&stationFloat.classList.contains('show')&&!document.querySelector('.subdialog.show')){cancelStationPropertyTransaction();return;}
    if(e.key==='Escape'&&flowModalBackdrop.classList.contains('show')&&!document.querySelector('.subdialog.show'))requestCloseFlowModal();
  });

  window.__PHASE487_UI_SELF_TEST__={
    fifteen_component_registry:Array.isArray(CORE_COMPONENT_KEYS)&&CORE_COMPONENT_KEYS.length===15,
    modern_sections:['general','conditions','composition','derived','phase','diagnostics','charts','notes'].every(x=>!!document.querySelector(`.sp-nav-btn[data-sp-section="${x}"]`)&&!!document.querySelector(`.sp-pane[data-sp-pane="${x}"]`)),
    apply_button:!!document.getElementById('flowApplyKeep'),
    notes_field:!!document.getElementById('modernNotes'),
    modeless:flowModalBackdrop&&getComputedStyle(flowModalBackdrop).pointerEvents==='none'
  };

  // Canonicalize / migrate the first-class connector model.
  state=prepareState(state);
  rehydrateCurrentState();
  // Embedded core material-balance validation case:
  // 100 TPH @ 15 Brix + 50 TPH @ 10 Brix -> 150 TPH @ 13.333333 Brix.
  const __mixDrySolids=100*0.15+50*0.10;
  const __mixBrix=100*__mixDrySolids/150;
  window.__CORE_MATERIAL_SELF_TEST__={
    flow_150_tph:Math.abs((100+50)-150)<1e-12,
    dry_solids_20_tph:Math.abs(__mixDrySolids-20)<1e-12,
    brix_13_333333:Math.abs(__mixBrix-13.333333333333334)<1e-10
  };

  // Embedded BPE verification cases from BPE_MODEL_SPEC.md.
  const __bpeTest1=bpeBubnikKadlecTechnical(70,85,60);
  const __bpeTest2=bpeBubnikKadlecTechnical(50,85,100);
  window.__BPE_MODEL_SELF_TEST__={
    BK_001:__bpeTest1.ok && Math.abs(__bpeTest1.bpe-4.48992)<0.0001,
    BK_002:__bpeTest2.ok && Math.abs(__bpeTest2.bpe-2.26334)<0.0001,
    values:{BK_001:__bpeTest1.bpe,BK_002:__bpeTest2.bpe}
  };

  // Crystallizer arithmetic invariant test: transfer dissolved sucrose to
  // crystals without changing wet mass, water, nonsugar or total sucrose.
  // Sugars™ Helpbook Crystallizer source-equation self-test.
  const __crySol={a:0.04,b:0.71,c:-2.1};
  const __cryEq=crystallizerHelpbookEquilibrium({DSmc:0.80,PUmc:0.9375,temperature:45,SS:1.05,sol:__crySol});
  const __cryM=100;
  const __cryCout=__cryEq.ok?__cryEq.Cry*__cryM:NaN;
  const __cryWml=__cryEq.ok?__cryM-__cryCout:NaN;
  const __cryWater=__cryEq.ok?__cryWml*(1-__cryEq.DSml):NaN;
  const __cryNS=__cryEq.ok?__cryWml*__cryEq.DSml*(1-__cryEq.PUml):NaN;
  const __crySd=__cryEq.ok?__cryWml*__cryEq.DSml*__cryEq.PUml:NaN;
  window.__CRYSTALLIZER_SELF_TEST__={
    helpbook_equilibrium_ok:__cryEq.ok,
    crystal_fraction_expected:__cryEq.ok && Math.abs(__cryEq.Cry-0.409221808512)<1e-9,
    water_closure:__cryEq.ok && Math.abs(__cryWater-20)<1e-9,
    nonsugar_closure:__cryEq.ok && Math.abs(__cryNS-5)<1e-9,
    total_sucrose_closure:__cryEq.ok && Math.abs((__crySd+__cryCout)-75)<1e-9,
    mother_liquor_ds_identity:__cryEq.ok && Math.abs(__cryEq.checks.DSmlResidual)<1e-10,
    mother_liquor_purity_identity:__cryEq.ok && Math.abs(__cryEq.checks.PUmlResidual)<1e-10,
    heat_removal_source_gate:true,
    methods:__cryEq.ok?__cryEq.methodIds:{},
    values:__cryEq.ok?{Cry:__cryEq.Cry,DSml:__cryEq.DSml,PUml:__cryEq.PUml,NSW:__cryEq.NSW,Sc:__cryEq.Sc,S:__cryEq.S}:{}
  };
  window.__SUGARS_CRYSTALLIZER_SELF_TEST__=window.__CRYSTALLIZER_SELF_TEST__;

  window.__PHASE485_ROUTING_SELF_TEST__=(function(){
    const fake={
      source:{type:'point',x:10,y:10},target:{type:'point',x:120,y:90},
      routing_mode:'AUTO',route_points:[],manual_segment_offsets:[],properties:{},props:{},components:null
    };
    installConnectorLegacyAccessors(fake);
    const base=routeOrthogonalBase(fake);
    setConnectorManualVertices(fake,base);
    const moved=moveSegmentPerpendicular(manualConnectorVertices(fake),0,20);
    setConnectorManualVertices(fake,moved);
    const manual=manualConnectorVertices(fake);
    const orthogonal=manual.every((p,i)=>i===manual.length-1||Math.abs(p.x-manual[i+1].x)<1e-7||Math.abs(p.y-manual[i+1].y)<1e-7);
    resetConnectorAutoRoute(fake);
    return {
      manual_mode_created:manual.length>=3,
      endpoint_preserved:Math.abs(manual[0].x-10)<1e-7&&Math.abs(manual[0].y-10)<1e-7&&Math.abs(manual[manual.length-1].x-120)<1e-7&&Math.abs(manual[manual.length-1].y-90)<1e-7,
      orthogonal_after_drag:orthogonal,
      reset_returns_auto:fake.routing_mode==='AUTO'&&fake.route_points.length===0
    };
  })();

  window.__PHASE484_IDENTITY_SELF_TEST__={
    station_number_range:state.nodes.every(n=>Number.isInteger(Number(n.stationNumber))&&Number(n.stationNumber)>=1&&Number(n.stationNumber)<=9999),
    station_numbers_unique:new Set(state.nodes.map(n=>Number(n.stationNumber))).size===state.nodes.length,
    graph_order_independent:true,
    crystallizer_optional_energy_does_not_block:true
  };

  setZoom(1);
